        if not s:  # Edge case for empty string
            return 0

        p = 0
        for i in range(1, k + 1):
            if i * i % k == 0:
                p = i
                break

        p = 2 * p

        sumdict = {i: {} for i in range(p)}
        cursum = 0
        vowels = {'a', 'e', 'i', 'o', 'u'}
        count = 0

        for i in range(len(s)):
            if s[i] in vowels:
                cursum += 1
            else:
                cursum -= 1

            cate = i % p

            if cursum in sumdict:
                if cate in sumdict[cursum]:
                    count += sumdict[cursum][cate]
            else:
                sumdict[cursum] = {}

            if cate in sumdict[cursum]:
                sumdict[cursum][cate] += 1
            else:
                sumdict[cursum][cate] = 1

        return count

