class Solution:
    def lexicographicallySmallestArray(self, nums: List[int], limit: int) -> List[int]:
        n = len(nums)
        nums2 = sorted(nums)
        indices = []
        result = [0] * n

        i = 0
        while i < n:
            if i == 0 or abs(nums[i] - nums[i - 1]) > limit:
                indices.append([])
            indices[-1].append(i)
            i += 1

        for group in indices:
            sortedIndex = sorted(group)
            sortedValues = sorted(nums[i] for i in group)
            for j in range(len(sortedIndex)):
                result[sortedIndex[j]] = sortedValues[j]

        return result

